WITH store_agg AS ( SELECT sr_store_sk, SUM(sr_net_loss) AS total_net_loss, AVG(sr_return_amt) AS avg_return_amt, COUNT(*) AS return_cnt FROM store_returns WHERE sr_return_ship_cost > 1000 AND sr_return_time_sk IN (46418, 47480, 37700) GROUP BY sr_store_sk ), website_filter AS ( SELECT web_site_sk, web_state, web_tax_percentage FROM web_site WHERE web_country = 'United States' AND web_tax_percentage > 0 ) SELECT sr.sr_store_sk, sr.sr_customer_sk, sr.sr_return_amt, sr.sr_net_loss, sa.total_net_loss, sa.avg_return_amt, ws.web_state, ws.web_tax_percentage, (sr.sr_net_loss / sa.total_net_loss) AS loss_ratio, RANK() OVER (PARTITION BY sr.sr_store_sk ORDER BY sr.sr_net_loss DESC) AS loss_rank FROM store_returns sr JOIN store_agg sa ON sr.sr_store_sk = sa.sr_store_sk CROSS JOIN website_filter ws WHERE sr.sr_return_quantity > 0 ORDER BY sa.total_net_loss DESC, loss_rank LIMIT 100
